  #define AUXPLL_AUXPLLCTRL_FREQUENCY_FREQUENCY_MinimumDiv (0x0000UL) /*!< Division ratio of 4                                 */
  #define AUXPLL_AUXPLLCTRL_FREQUENCY_FREQUENCY_Audio44k1 (0x3BCDUL) /*!< Division ratio for audio 44.1kHz frequency family    */
  #define AUXPLL_AUXPLLCTRL_FREQUENCY_FREQUENCY_USB24M (0x8000UL) /*!< Division ratio for USB PHY 24MHz clock                  */
