  #define EGU_INTPEND_TRIGGERED14_NotPending (0x0UL) /*!< Read: Not pending                                                    */
  #define EGU_INTPEND_TRIGGERED14_Pending (0x1UL)    /*!< Read: Pending                                                        */

/* TRIGGERED15 @Bit 15 : Read pending status of interrupt for event TRIGGERED[15] */
  #define EGU_INTPEND_TRIGGERED15_Pos (15UL)         /*!< Position of TRIGGERED15 field.                                       */
  #define EGU_INTPEND_TRIGGERED15_Msk (0x1UL << EGU_INTPEND_TRIGGERED15_Pos) /*!< Bit mask of TRIGGERED15 field.               */
  #define EGU_INTPEND_TRIGGERED15_Min (0x0UL)        /*!< Min enumerator value of TRIGGERED15 field.                           */
  #define EGU_INTPEND_TRIGGERED15_Max (0x1UL)        /*!< Max enumerator value of TRIGGERED15 field.                           */
  #define EGU_INTPEND_TRIGGERED15_NotPending (0x0UL) /*!< Read: Not pending                                                    */
  #define EGU_INTPEND_TRIGGERED15_Pending (0x1UL)    /*!< Read: Pending                                                        */


