  #define MCAN_CCCR_TEST_Pos (7UL)                   /*!< Position of TEST field.                                              */
  #define MCAN_CCCR_TEST_Msk (0x1UL << MCAN_CCCR_TEST_Pos) /*!< Bit mask of TEST field.                                        */
