/* FDOE @Bit 8 : FD Operation Enable */
  #define MCAN_CCCR_FDOE_Pos (8UL)                   /*!< Position of FDOE field.                                              */
  #define MCAN_CCCR_FDOE_Msk (0x1UL << MCAN_CCCR_FDOE_Pos) /*!< Bit mask of FDOE field.                                        */
