/* READ @Bits 0..1 : OTP mempory read mode. */
  #define OTPC_TESTMODE1_EMEMORY_READ_READ_Pos (0UL) /*!< Position of READ field.                                              */
  #define OTPC_TESTMODE1_EMEMORY_READ_READ_Msk (0x3UL << OTPC_TESTMODE1_EMEMORY_READ_READ_Pos) /*!< Bit mask of READ field.    */
  #define OTPC_TESTMODE1_EMEMORY_READ_READ_Min (0x0UL) /*!< Min enumerator value of READ field.                                */
