  #define RADIO_RXAGC_GAIN_AGCRFGAINSTEPUP_Msk (0xFUL << RADIO_RXAGC_GAIN_AGCRFGAINSTEPUP_Pos) /*!< Bit mask of AGCRFGAINSTEPUP
                                                                            field.*/

/* AGCRFGAINSTEPDOWN @Bits 12..15 : gain step for decreasing RF gain */
  #define RADIO_RXAGC_GAIN_AGCRFGAINSTEPDOWN_Pos (12UL) /*!< Position of AGCRFGAINSTEPDOWN field.                              */
  #define RADIO_RXAGC_GAIN_AGCRFGAINSTEPDOWN_Msk (0xFUL << RADIO_RXAGC_GAIN_AGCRFGAINSTEPDOWN_Pos) /*!< Bit mask of
                                                                            AGCRFGAINSTEPDOWN field.*/

/* AGCIFGAINMAX @Bits 16..19 : Maximum gain of IF gain */
  #define RADIO_RXAGC_GAIN_AGCIFGAINMAX_Pos (16UL)   /*!< Position of AGCIFGAINMAX field.                                      */
  #define RADIO_RXAGC_GAIN_AGCIFGAINMAX_Msk (0xFUL << RADIO_RXAGC_GAIN_AGCIFGAINMAX_Pos) /*!< Bit mask of AGCIFGAINMAX field.  */

/* AGCIFGAINMIN @Bits 20..23 : Minimum gain of IF gain */
  #define RADIO_RXAGC_GAIN_AGCIFGAINMIN_Pos (20UL)   /*!< Position of AGCIFGAINMIN field.                                      */
  #define RADIO_RXAGC_GAIN_AGCIFGAINMIN_Msk (0xFUL << RADIO_RXAGC_GAIN_AGCIFGAINMIN_Pos) /*!< Bit mask of AGCIFGAINMIN field.  */

/* AGCIFGAINSTEPUP @Bits 24..27 : gain step for increasing IF gain */
  #define RADIO_RXAGC_GAIN_AGCIFGAINSTEPUP_Pos (24UL) /*!< Position of AGCIFGAINSTEPUP field.                                  */
  #define RADIO_RXAGC_GAIN_AGCIFGAINSTEPUP_Msk (0xFUL << RADIO_RXAGC_GAIN_AGCIFGAINSTEPUP_Pos) /*!< Bit mask of AGCIFGAINSTEPUP
                                                                            field.*/

/* AGCIFGAINSTEPDOWN @Bits 28..31 : gain step for decreasing IF gain */
  #define RADIO_RXAGC_GAIN_AGCIFGAINSTEPDOWN_Pos (28UL) /*!< Position of AGCIFGAINSTEPDOWN field.                              */
  #define RADIO_RXAGC_GAIN_AGCIFGAINSTEPDOWN_Msk (0xFUL << RADIO_RXAGC_GAIN_AGCIFGAINSTEPDOWN_Pos) /*!< Bit mask of
                                                                            AGCIFGAINSTEPDOWN field.*/


