  #define RADIO_RXAGC_STATUS_ResetValue (0x0000007FUL) /*!< Reset value of STATUS register.                                    */

/* RSSI @Bits 0..6 : Raw status of received signal strength indicator, directly from RxAgc without buffering */
  #define RADIO_RXAGC_STATUS_RSSI_Pos (0UL)          /*!< Position of RSSI field.                                              */
  #define RADIO_RXAGC_STATUS_RSSI_Msk (0x7FUL << RADIO_RXAGC_STATUS_RSSI_Pos) /*!< Bit mask of RSSI field.                     */

