  #define RADIO_ADPLLCOMPANIONBACKDOORS_FLIPSSEL_Msk (0x1UL << RADIO_ADPLLCOMPANIONBACKDOORS_FLIPSSEL_Pos) /*!< Bit mask of
                                                                            FLIPSSEL field.*/

/* REQUESTCLOCKOVERRIDE @Bit 1 : In normal operation we request clock when pwrupFsLdoDig0 is set. By setting this to 1, we will
                                 request clock even when pwrupFsLdoDig0. This may be useful for current measurements of FS_DIG */

  #define RADIO_ADPLLCOMPANIONBACKDOORS_REQUESTCLOCKOVERRIDE_Pos (1UL) /*!< Position of REQUESTCLOCKOVERRIDE field.            */
  #define RADIO_ADPLLCOMPANIONBACKDOORS_REQUESTCLOCKOVERRIDE_Msk (0x1UL << RADIO_ADPLLCOMPANIONBACKDOORS_REQUESTCLOCKOVERRIDE_Pos)
                                                                            /*!< Bit mask of REQUESTCLOCKOVERRIDE field.*/

/* OVRENCK32MCORE @Bit 2 : Make it possible to manually control whether ck32MCore is sent to the AdPll digital island. Needed to
                           test complete clock silence in the AdPll island. It can also be used to enable the clock activity on
                           the clock net even when the clock is not selected. */

  #define RADIO_ADPLLCOMPANIONBACKDOORS_OVRENCK32MCORE_Pos (2UL) /*!< Position of OVRENCK32MCORE field.                        */
  #define RADIO_ADPLLCOMPANIONBACKDOORS_OVRENCK32MCORE_Msk (0x1UL << RADIO_ADPLLCOMPANIONBACKDOORS_OVRENCK32MCORE_Pos) /*!< Bit
                                                                            mask of OVRENCK32MCORE field.*/

