  #define RICR_UROT_RECOVERY_SMWD_SM_TBS_FW_DIGEST_VALUE_Pos (0UL) /*!< Position of VALUE field.                               */
  #define RICR_UROT_RECOVERY_SMWD_SM_TBS_FW_DIGEST_VALUE_Msk (0xFFFFFFFFUL << RICR_UROT_RECOVERY_SMWD_SM_TBS_FW_DIGEST_VALUE_Pos)
                                                                            /*!< Bit mask of VALUE field.*/
