  #define RICR_UROT_RECOVERY_SMWD_SM_TBS_FW_VERSION_MaxCount (4UL) /*!< Max size of VERSION[4] array.                          */
  #define RICR_UROT_RECOVERY_SMWD_SM_TBS_FW_VERSION_MaxIndex (3UL) /*!< Max index of VERSION[4] array.                         */
