/* SICR_UROT_RECOVERY_SM_TBS_POLICY_UPDATE: Enable or Disable firmware update. */

/* ENABLE @Bits 0..31 : Possible values for this register. */
  #define SICR_UROT_RECOVERY_SM_TBS_POLICY_UPDATE_ENABLE_Pos (0UL) /*!< Position of ENABLE field.                              */
  #define SICR_UROT_RECOVERY_SM_TBS_POLICY_UPDATE_ENABLE_Msk (0xFFFFFFFFUL << SICR_UROT_RECOVERY_SM_TBS_POLICY_UPDATE_ENABLE_Pos)
