  #define SICR_AROT_SECURE_OEMPUBKEY_RFU_MinIndex (0UL) /*!< Min index of RFU[2] array.                                        */

/* VALUE @Bits 0..31 : RFU word [o]. */
  #define SICR_AROT_SECURE_OEMPUBKEY_RFU_VALUE_Pos (0UL) /*!< Position of VALUE field.                                         */
